// ==========================================
// BELTAGY PORTFOLIO - SEARCH SYSTEM (Fuse.js)
// ==========================================

document.addEventListener('DOMContentLoaded', () => {
    const searchInput = document.getElementById('search-input');
    const searchResults = document.getElementById('search-results');
    
    // We only initialize if the search elements exist
    if (!searchInput || !searchResults) return;

    let fuse;

    // Fetch the index.json generated by Hugo
    fetch(window.searchIndexUrl)
        .then(response => response.json())
        .then(data => {
            // Initialize Fuse.js with the data
            const options = {
                keys: ['title', 'content', 'summary'],
                threshold: 0.4, // Lower threshold means stricter matching
                ignoreLocation: true,
                useExtendedSearch: true
            };
            fuse = new Fuse(data, options);
        })
        .catch(err => {
            console.error('Failed to load search index:', err);
            searchResults.innerHTML = '<div class="p-4 text-red-500 text-center text-sm font-ibm">تعذر تحميل بيانات البحث.</div>';
        });

    // Listen to input events
    searchInput.addEventListener('input', (e) => {
        const query = e.target.value.trim();
        
        if (!query) {
            searchResults.innerHTML = '';
            searchResults.classList.add('hidden');
            return;
        }

        if (!fuse) return; // Not loaded yet

        const results = fuse.search(query);
        
        if (results.length === 0) {
            searchResults.innerHTML = '<div class="p-4 text-center text-sm font-ibm opacity-70" style="color:var(--text-ambient);">لا توجد نتائج مطابقة لبحثك.</div>';
            searchResults.classList.remove('hidden');
            return;
        }

        // Render results
        let html = '';
        // Limit to top 8 results
        const topResults = results.slice(0, 8);
        
        topResults.forEach(item => {
            const page = item.item;
            
            // Map types to human readable Arabic labels
            let typeLabel = '';
            let typeIcon = '';
            let typeColor = '';
            
            if (page.type === 'poetry') {
                typeLabel = 'قصيدة';
                typeIcon = 'feather';
                typeColor = 'var(--gold-antique)';
            } else if (page.type === 'quotes') {
                typeLabel = 'قطوف';
                typeIcon = 'quote';
                typeColor = 'var(--teal-400)';
            } else if (page.type === 'thoughts') {
                typeLabel = 'خاطرة';
                typeIcon = 'lightbulb';
                typeColor = 'var(--violet-500)';
            }
            
            html += `
                <a href="${page.permalink}" class="block p-4 border-b hover:bg-gold-antique/5 transition-colors group" style="border-color: rgba(197,160,89,0.1); text-decoration: none;">
                    <div class="flex items-center gap-3 mb-1">
                        <span class="p-1.5 rounded-lg flex items-center justify-center bg-opacity-10" style="background-color: ${typeColor}20; color: ${typeColor};">
                            <i data-lucide="${typeIcon}" class="w-3 h-3"></i>
                        </span>
                        <span class="text-xs font-ibm font-bold" style="color: ${typeColor}; opacity: 0.9;">${typeLabel}</span>
                    </div>
                    <h4 class="font-reem font-bold text-base mb-1 group-hover:text-gold-antique transition-colors" style="color: var(--text-offwhite);">${page.title}</h4>
                    <p class="font-ibm text-xs line-clamp-2 leading-relaxed" style="color: var(--text-muted);">${page.summary || page.content.substring(0, 100) + '...'}</p>
                </a>
            `;
        });

        searchResults.innerHTML = html;
        searchResults.classList.remove('hidden');
        if (typeof lucide !== 'undefined') lucide.createIcons();
    });
});
